@tool
def preparer_courriel(destinataire: str, corps: str) -> dict:
    """Prepare un courriel. Il ne part qu'apres validation dans l'interface."""
    brouillon = drafts.create(destinataire=destinataire, corps=corps)
    return {"draft_id": brouillon.id, "statut": "en_attente_de_validation"}

# L'envoi n'est pas expose au modele : il est declenche par l'interface,
# apres que l'utilisateur a vu le contenu exact.
def envoyer_apres_validation(draft_id: str, actor: User) -> None:
    brouillon = drafts.get(draft_id, owner=actor)
    smtp.send(brouillon.destinataire, brouillon.corps)
    audit.log("courriel.envoye", actor=actor.id, draft=draft_id)

